/* AUNO pilot — lightweight SPA, no external JS dependencies. All remote writes go through the demo API. */
'use strict';
const API = '/api';
const S = {data:null, userId:Number(localStorage.getItem('auno-demo-user')||1), page:null, filter:'All', circleFilter:'All', storageArea:'All areas', search:'', modal:null, journey:null, latestCode:null, busy:false,nowMood:'people',nowTime:4,nowBudget:'free',insightsDays:30,insightsCategory:'All',bizBookings:1000,bizTicket:80,bizTake:12};
const E = (v='') => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const q = s => document.querySelector(s);
const asset = name => `assets/${encodeURIComponent(name||'city')}.svg`;
const img = (name, cls='', alt='Illustrated city experience') => `<img class="${cls}" src="${asset(name)}" alt="${E(alt)}" loading="lazy">`;
const money = n => Number(n||0)===0?'Free':`AED ${Number(n).toLocaleString('en-AE')}`;
function formatDate(value,format='full') {if(!value)return 'TBC';const d=new Date(value);if(Number.isNaN(+d))return value;let opts=format==='short'?{day:'numeric',month:'short'}:format==='weekday'?{weekday:'short',day:'numeric',month:'short'}:{weekday:'short',day:'numeric',month:'short',hour:'numeric',minute:'2-digit',hour12:true};return new Intl.DateTimeFormat('en-GB',opts).format(d)}
const timeOnly = val => {const d=new Date(val);return Number.isNaN(+d)?String(val).slice(11,16):new Intl.DateTimeFormat('en-GB',{hour:'numeric',minute:'2-digit',hour12:true}).format(d)};
const day = v => {const d=new Date(v);return isNaN(+d)?'--':d.getDate()};
const mon = v => {const d=new Date(v);return isNaN(+d)?'---':d.toLocaleString('en-GB',{month:'short'})};
const today = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const future = n => {const d=new Date(); d.setDate(d.getDate()+n); return d.toISOString().slice(0,10)};
const roleName = r => ({member:'Member',host:'Community host',partner:'Storage partner',admin:'AUNO operations'})[r]||r;
const categories=['All','Padel','Badminton','Culture','Food','Adventure'];
const intOptions=['Padel','Badminton','Food','Photography','Culture','Architecture','Adventure','Art','Outdoors','Sports'];
const data = () => S.data||{};
const me = () => data().me||{};
const initials = u => (u?.avatar||'AU');
const picture = (u,cls='') => `<span class="avatar ${cls}">${E(initials(u))}</span>`;
const pill=(text,type='')=>`<span class="pill ${type}">${E(text)}</span>`;
const header=(title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">AUNO / ${E(title)}</div><h1 style="margin-top:10px">${E(title)}</h1>${desc?`<p>${E(desc)}</p>`:''}</div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;
const section=(title,subtitle,action='')=>`<div class="section-head"><div><h2>${E(title)}</h2>${subtitle?`<p>${E(subtitle)}</p>`:''}</div>${action}</div>`;
const empty=(emoji,title,desc,action='')=>`<div class="empty"><div class="emoji">${emoji}</div><b>${E(title)}</b><p>${E(desc)}</p>${action}</div>`;
const btn=(label,attrs='',variant='')=>`<button type="button" class="btn ${variant}" ${attrs}>${label}</button>`;
const A = name => `<span aria-hidden="true">${name}</span>`;
const yesno = n => n ? 'Yes' : 'No';
async function api(path,method='GET',body=null){
  const opts={method,headers:{'X-Demo-User':String(S.userId)}};
  if(body!==null){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}
  const res=await fetch(API+path,opts);let out={};try{out=await res.json()}catch{}
  if(!res.ok){const detail=out.detail;throw new Error(typeof detail==='string'?detail:'Please review your input and try again.')}return out;
}
async function refresh(render=true){S.data=await api('/bootstrap');if(render)draw()}
async function mutate(path,body=null,success='Updated successfully',method='POST'){
  if(S.busy)return;
  S.busy=true;
  try{let out=await api(path,method,body);S.modal=null;await refresh();toast(out.message||success);if(out.code)S.latestCode=out.code;return out}
  catch(e){toast(e.message,true);return null}
  finally{S.busy=false}
}
let toastTimer;
function toast(text,isError=false){const root=q('#toast-root');if(!root)return;root.innerHTML=`<div class="toast ${isError?'error':''}"><b>${isError?'Something needs attention':'All set'}</b>${E(text)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>root.innerHTML='',4200)}
const NAVS={
  member:[['home','⌂','Home'],['now','✦','AUNO Now'],['life','✺','AUNO Life'],['discover','⌕','Discover'],['people','♧','People'],['moments','▦','Moments'],['circles','◎','Communities'],['journeys','◇','Journeys'],['stow','▣','Luggage storage'],['plans','✣','Social plans'],['rewards','✧','Rewards'],['inbox','▤','Inbox'],['profile','◉','My profile']],
  host:[['host','▥','Host studio'],['hostos','⚒','HostOS'],['life','✺','AUNO Life'],['discover','⌕','Discover'],['people','♧','People'],['moments','▦','Moments'],['circles','◎','Communities'],['plans','✣','Social plans'],['inbox','▤','Inbox'],['profile','◉','Profile']],
  partner:[['partner','▦','Partner studio'],['business','▦','For Business'],['life','✺','AUNO Life'],['stow','▣','Storage network'],['inbox','▤','Inbox'],['profile','◉','Profile']],
  admin:[['insights','▥','Mission Control'],['business','▦','Business pilots'],['life','✺','AUNO Life'],['admin','▤','Operations'],['discover','⌕','Activities'],['circles','◎','Communities'],['inbox','▤','Inbox'],['profile','◉','Profile']]
};
function navHtml(){const items=NAVS[me().role]||NAVS.member;const unread=data().notifications?.some(n=>!n.is_read);
return `<aside class="sidebar" aria-label="Primary navigation"><div class="brand"><span class="brand-symbol" aria-hidden="true">a</span><div><div class="brand-name">auno</div><div class="brand-sub">life, together.</div></div></div><div class="side-label">Your world</div><nav class="side-nav">${items.map(([id,icon,label])=>`<button class="nav-item ${S.page===id?'active':''}" data-page="${id}" aria-current="${S.page===id?'page':'false'}"><span class="symbol">${icon}</span><span>${label}</span>${id==='inbox'&&unread?'<i class="nav-dot"></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><strong>Life happens together.</strong><p>Find your people. Make your next plan.</p></div><div class="sidebar-foot"><span>● PILOT EXPERIENCE</span><span>v3.0</span></div></div></aside>`}
function topHtml(){const u=me();const unread=data().notifications?.some(n=>!n.is_read);
return `<header class="topbar"><div class="top-left"><span class="breadcrumbs">AUNO <span style="color:#bcc6bc;padding:0 8px">/</span> <b>${E((NAVS[u.role]||NAVS.member).find(x=>x[0]===S.page)?.[2]||AUNO_SUITE_PAGES[S.page]||'Home')}</b></span></div><div class="top-right"><form class="searchbox" data-form="search"><span style="font-size:18px">⌕</span><input name="q" value="${E(S.search)}" placeholder="People, places, experiences" aria-label="Search experiences"/></form>${aunoThemeControls(true)}${u.role==='member'?`<div class="mode-toggle" aria-label="Account mode"><button type="button" class="${u.mode==='resident'?'active':''}" data-mode="resident">Resident</button><button type="button" class="${u.mode==='visitor'?'active':''}" data-mode="visitor">Visitor</button></div>`:''}<button class="icon-btn" aria-label="Notifications" data-page="inbox">♧${unread?'<i class="notice-count"></i>':''}</button><button class="persona" data-modal="personas" title="Switch demo persona">${picture(u)}<span><strong>${E(u.name.split(' ')[0])}⌄</strong><small>${E(roleName(u.role))}</small></span></button></div></header>`}
function mobileHtml(){const it=NAVS[me().role]||NAVS.member;const priority=me().role==='member'?['home','discover','journeys','circles','profile']:[it[0][0],it[1]?.[0],it[2]?.[0],'inbox','profile'];return `<nav class="mobile-nav" aria-label="Mobile navigation">${priority.filter(Boolean).map(id=>{const i=it.find(x=>x[0]===id);if(!i)return '';return `<button data-page="${id}" class="${S.page===id?'active':''}"><span>${i[1]}</span>${E(i[2])}</button>`}).join('')}</nav>`}
function skeleton(){return '<div class="loading-state"><div class="spinner" aria-label="Loading"></div></div>'}
function draw(){const app=q('#app');if(!app)return;if(!S.data){app.innerHTML=skeleton();return};if(!S.page)S.page=({member:'home',host:'host',partner:'partner',admin:'insights'})[me().role]||'home';if(!(NAVS[me().role]||NAVS.member).some(x=>x[0]===S.page)&&!Object.prototype.hasOwnProperty.call(AUNO_SUITE_PAGES,S.page))S.page=({member:'home',host:'host',partner:'partner',admin:'insights'})[me().role];
const content={life:()=>aunoSuitePage('life'),together:()=>aunoSuitePage('together'),passport:()=>aunoSuitePage('passport'),concierge:()=>aunoSuitePage('concierge'),lens:()=>aunoSuitePage('lens'),homebase:()=>aunoSuitePage('homebase'),hostos:()=>aunoSuitePage('hostos'),business:()=>aunoSuitePage('business'),home:homePage,now:aunoNowPage,insights:aunoInsightsPage,discover:discoverPage,people:peoplePage,moments:momentsPage,circles:circlesPage,journeys:journeysPage,stow:stowPage,plans:plansPage,rewards:rewardsPage,inbox:inboxPage,profile:profilePage,host:hostPage,partner:partnerPage,admin:adminPage}[S.page]||homePage;
app.innerHTML=`<div class="app-shell">${navHtml()}<div class="main-shell">${topHtml()}<main class="content"><div class="demo-strip"><span><b>Public interactive demo.</b> Fictional data is stored only in this browser. No real accounts, payments, storage or verification.</span><span class="pill orange">DEMO</span></div>${content()}<div class="footer-line">AUNO · Public browser-only demo; no real marketplace or shared accounts. Designed for belonging.</div></main></div>${mobileHtml()}</div>${modalHtml()}`;
window.scrollTo({top:0,behavior:'instant'});
}
function dateBlock(e){return `<div class="date-block"><b>${day(e.start_at)}</b><small>${mon(e.start_at)}</small></div>`}
function eventCard(e){const isBooked=!!e.my_booking;return `<article class="event-card"><div class="card-art">${img(e.cover,'',e.category+' illustration')}<div class="art-overlay">${pill(e.category,'dark')}</div><button class="art-save" aria-label="View ${E(e.title)}" data-open-event="${e.id}">↗</button></div><div class="card-content"><h3>${E(e.title)}</h3><div class="meta">◷ ${E(formatDate(e.start_at,'weekday'))} · ${E(timeOnly(e.start_at))}</div><div class="meta">⌖ ${E(e.area)} <i>•</i> ${E(e.level)}</div><div class="card-footer"><div><div class="price">${money(e.price)}</div><div class="member-count">${e.booked} / ${e.capacity} spots reserved</div></div>${btn(isBooked?'View booking':'View details',`data-open-event="${e.id}"`,'secondary small')}</div></div></article>`}
function circleCard(c){const status=c.membership?.status;return `<article class="circle-card"><div class="card-art">${img(c.cover,'',c.category+' community illustration')}<div class="art-overlay">${pill(c.category,'dark')}</div></div><div class="card-content"><h3>${E(c.name)}</h3><p>${E(c.description)}</p><div class="pill-row">${pill('⌖ '+c.area,'outline')}${pill(c.visibility==='approval'?'Application to join':'Open to join',c.visibility==='approval'?'orange':'green')}</div><div class="card-footer"><div><div class="small-avatars"><i>MC</i><i>SR</i><i>NW</i></div><div class="member-count">${c.members} members</div></div>${btn(status==='joined'?'Joined ✓':status==='pending'?'Pending review':'Join circle',status?`disabled`:`data-join-community="${c.id}"`,'secondary small')}</div></div></article>`}
function storeCard(p){return `<article class="store-card"><div class="card-art">${img(p.cover,'','Demo luggage storage illustration')}<div class="art-overlay">${pill('Demo venue','dark')}</div></div><div class="card-content"><h3>${E(p.name)}</h3><div class="meta">⌖ ${E(p.area)} · ${E(p.open_time)}–${E(p.close_time)}</div><div class="meta">▣ Capacity: ${p.capacity} bags · Managed handoff</div><div class="info-row"><div class="rate">${money(p.price_per_bag)} <small>/ bag · demo</small></div>${btn('Reserve',`data-open-storage="${p.id}"`,'secondary small')}</div></div></article>`}
function planCard(p){return `<article class="plan-card">${pill(p.category||'Social','green')}<h3>${E(p.title)}</h3><div class="meta">◷ ${E(formatDate(p.start_at))}<br>⌖ ${E(p.area)}</div><p style="margin-top:9px">${E(p.description)}</p><div class="avatar-row">${picture({avatar:(p.host_name||'A').split(' ').map(x=>x[0]).join('')},'v2')}<small>Hosted by ${E(p.host_name)} · ${p.joined}/${p.seats} going</small></div><div class="card-footer"><div class="member-count">${p.seats-p.joined} spots left</div>${btn(p.my_member?'You’re going ✓':'Join plan',p.my_member?'disabled':`data-join-plan="${p.id}"`,'secondary small')}</div></article>`}
function homePage(){const u=me();const visitor=u.mode==='visitor';const booked=data().eventBookings||[];const recommendations=[...data().events].sort((a,b)=>Number(u.interests.includes(b.category))-Number(u.interests.includes(a.category))||Number(b.featured)-Number(a.featured)).slice(0,3);const myCircles=data().communities.filter(c=>c.membership?.status==='joined').slice(0,3);
return `<div class="page-head"><div><div class="eyebrow">WELCOME TO YOUR CITY</div><h1 style="margin-top:10px">Hello, ${E(u.name.split(' ')[0])} <span style="font-size:31px">✳</span></h1><p>${visitor?'Make every moment of your visit count.':'Good people. Great plans. Your Dubai starts here.'}</p></div><div class="page-actions">${pill('● Dubai, UAE','green')}${btn('Switch demo persona ▾','data-modal="personas"','outline')}</div></div>
<div class="hero"><div class="hero-copy"><div class="eyebrow light">${visitor?'THE CITY IS WAITING':'BELONG SOMEWHERE BRILLIANT'}</div><h1>${visitor?'Travel more. <em>Feel at home.</em>':'Find your people. <em>Make the city yours.</em>'}</h1><p>${visitor?'Discover local communities, explore places together and turn spare hours into standout memories.':'Join a game, discover a circle, make a plan. Your best days start with the people you share them with.'}</p><div class="hero-buttons">${btn(visitor?'Build my itinerary':'Explore experiences',`data-page="${visitor?'journeys':'discover'}"`,'brandlime')}${btn(visitor?'Find a circle':'Explore communities',`data-page="circles"`,'light')}</div></div><div class="hero-visual">${img(visitor?'marina':'city','','Stylised Dubai skyline')}<div class="floating-note"><div class="note-icon">✦</div><div><b>Your next moment awaits</b><small>Made for real connections</small></div></div></div></div>
<div class="quick-actions">${[['🎾','Find a game','Sports & sessions','discover'],['♧','Meet new people','Shared interests & intent','people'],['✈','Plan a journey','Explore Dubai smarter','journeys'],['▣','Drop your bags','Travel light & free','stow']].map(([ic,t,sub,pg])=>`<button class="quick-card" data-page="${pg}"><span class="quick-icon">${ic}</span><span><b>${t}</b><small>${sub}</small></span></button>`).join('')}</div>
<section class="section">${section('Chosen for you','Experiences to turn an ordinary day into something memorable.',`<button class="text-link" data-page="discover">Explore all activities →</button>`)}<div class="cards-grid">${recommendations.map(eventCard).join('')}</div></section>
<section class="section"><div class="split"><div class="panel"><div class="panel-head"><div><h3>Your upcoming experiences</h3><div class="panel-sub">A little to look forward to</div></div>${btn('Discover more','data-page="discover"','outline small')}</div>${booked.length?booked.slice(0,3).map(b=>`<div class="my-next">${dateBlock(b)}<div style="flex:1"><strong>${E(b.title)}</strong><p>${E(b.venue)} · ${E(timeOnly(b.start_at))}</p></div>${pill('Confirmed','green')}</div>`).join(''):empty('✧','Your calendar has room for great things','Find a session, book a spot and start making memories.',btn('Explore activities','data-page="discover"','secondary small'))}</div><div class="panel"><div class="panel-head"><div><h3>Your communities</h3><div class="panel-sub">The circles that feel like home</div></div><button class="text-link" data-page="circles">View all →</button></div>${myCircles.length?myCircles.map(c=>`<div class="circle-item">${img(c.cover,'circle-mini')}<div><b>${E(c.name)}</b><small>${E(c.category)} · ${c.members} members</small></div><span class="right">→</span></div>`).join(''):empty('◎','Find your people','Join your first community.')}</div></div></section>
<section class="section"><div class="story-banner"><div><div class="eyebrow">EXPERIENCES, MADE HUMAN</div><h3 style="margin-top:11px">The best travel stories start with a simple hello.</h3><p>Whether you have two hours or two weeks, turn your time in Dubai into a journey worth remembering.</p>${btn('Build a journey →','data-page="journeys"','secondary mt16')}</div>${img('marina','','Dubai skyline illustration')}</div></section>`}
function discoverPage(){const events=data().events.filter(e=>S.filter==='All'||e.category===S.filter).filter(e=>!S.search||`${e.title} ${e.area} ${e.category} ${e.venue}`.toLowerCase().includes(S.search.toLowerCase()));
return `${header('Discover','Find something that feels like you. Book a spot, show up, and let good things happen.',btn('+ Create a social plan','data-modal="create-plan"'))}<div class="toolbar"><div class="chipbar">${categories.map(c=>`<button class="chip ${S.filter===c?'active':''}" data-filter="${E(c)}">${E(c)}</button>`).join('')}</div>${pill(`${events.length} experiences`,'outline')}</div>${events.length?`<div class="cards-grid">${events.map(eventCard).join('')}</div>`:empty('⌕','No matches yet','Try another category or a different search.')}
<section class="section"><div class="story-banner"><div><div class="eyebrow">MAKE YOUR OWN MOMENT</div><h3 style="margin-top:10px">Have an idea for a great afternoon?</h3><p>Invite a small group to an interest-led plan. Real people, real experiences, better weekends.</p>${btn('Create a plan →','data-modal="create-plan"','secondary mt16')}</div>${img('food')}</div></section>`}
function circlesPage(){const cats=['All','Sports','Social','Interests','Adventure'];const communities=data().communities.filter(c=>S.circleFilter==='All'||c.category===S.circleFilter);
return `${header('Communities','Not just groups. Real connections that grow with every shared experience.',btn('+ Start a community','data-modal="create-community"'))}<div class="hero-small" style="margin-bottom:24px"><div><div class="eyebrow light">A COMMUNITY OF COMMUNITIES</div><h2>A place to find your people.</h2><p>Discover approved interest-based circles, join recurring activities, and find a sense of belonging in Dubai.</p></div>${img('desert')}</div><div class="toolbar"><div class="chipbar">${cats.map(c=>`<button class="chip ${S.circleFilter===c?'active':''}" data-circle-filter="${c}">${c}</button>`).join('')}</div>${pill(`${communities.length} approved circles`,'green')}</div><div class="cards-grid">${communities.map(circleCard).join('')}</div><section class="section">${section('Your community proposals','Every great circle starts with a good idea.')} ${data().myApplications?.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Community</th><th>Category</th><th>Area</th><th>Status</th></tr></thead><tbody>${data().myApplications.map(c=>`<tr><td><b>${E(c.name)}</b></td><td>${E(c.category)}</td><td>${E(c.area)}</td><td>${pill(c.status,c.status==='approved'?'green':'orange')}</td></tr>`).join('')}</tbody></table></div>`:empty('◎','Start something meaningful','Apply to create a new community, then let our team review it.',btn('+ Apply for a community','data-modal="create-community"','secondary'))}</section>`}
function journeysPage(){const saved=S.journey?{items:S.journey.items,days:Math.max(...S.journey.items.map(x=>x.day),1),area:'Dubai',budget:0}:data().journeys?.[0];const items=saved?.items||[];const interests=['Culture','Food','Architecture','Outdoors','Art','Sports','Adventure','Photography'];const supported=items.reduce((acc,p)=>{(acc[p.day] ||= []).push(p);return acc;},{});
return `${header('Journeys','Create a city itinerary around your interests, your time, your pace, and the people you want to meet.')}<div class="split" style="grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr)"><div class="panel"><div class="eyebrow">YOUR TRIP, YOUR RULES</div><h2 style="margin:11px 0 9px">Where shall we begin?</h2><p class="small-note">Tell us what matters. This pilot uses a curated rule-based planner; live opening hours, journeys and bookings are not yet integrated.</p><form data-form="journey" style="margin-top:22px"><div class="form-grid"><div class="field"><label for="j-area">Base neighbourhood</label><select name="area" id="j-area"><option>Dubai Marina</option><option>Downtown Dubai</option><option>Al Fahidi</option><option>JBR</option><option>Al Quoz</option><option>Deira</option></select></div><div class="field"><label for="j-days">Stay duration</label><select name="days" id="j-days">${[1,2,3,4,5,7,10,14].map(x=>`<option value="${x}" ${x===3?'selected':''}>${x} ${x===1?'day':'days'}</option>`).join('')}</select></div><div class="field"><label for="j-budget">Experience budget (AED)</label><input name="budget" id="j-budget" type="number" min="0" max="20000" value="500" required></div><div class="field"><label for="j-pace">Travel pace</label><select name="pace" id="j-pace"><option>Relaxed</option><option selected>Balanced</option><option>Packed</option></select></div><div class="field span-all"><label>I'm interested in…</label><div class="chips-check">${interests.map((v,i)=>`<label><input type="checkbox" name="interests" value="${v}" ${[0,1,2].includes(i)?'checked':''}>${v}</label>`).join('')}</div></div><div class="field span-all"><label style="display:flex;align-items:center;gap:8px;cursor:pointer"><input type="checkbox" name="social" checked style="width:15px;min-height:15px">Include group experiences and community suggestions</label></div></div><button type="submit" class="btn full">✦ &nbsp;Build my journey →</button></form></div><div class="journey-preview"><div class="flex justify-between align-center gap8"><div><div class="eyebrow">YOUR PERSONALISED PLAN</div><h2 style="margin-top:9px">${items.length?'Your Dubai itinerary':'A better way to explore.'}</h2></div>${pill(items.length?'Saved plan':'Ready when you are','green')}</div>${items.length?`<div class="notice-card mt16">Preview recommendations and sample costs only. Confirm opening hours, tickets, travel times and availability before travelling.</div>${Object.keys(supported).sort((a,b)=>a-b).map(d=>`<div class="journey-day"><h3>Day ${d} <span style="font-size:11px;color:#96a599;font-weight:500">· a little more to discover</span></h3>${supported[d].map(p=>`<div class="journey-stop"><span>${p.icon}</span><div style="flex:1"><b>${E(p.name)}</b><small>${E(p.area)} · ${p.minutes} min · ${money(p.cost)} · ${E(p.time)}</small></div>${pill(p.category,'outline')}</div>`).join('')}</div>`).join('')}<div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:20px">${btn('Find people to join','data-page="plans"','secondary')}${btn('Reserve luggage storage','data-page="stow"','outline')}</div>`:`<div class="journey-stage" style="text-align:center;padding:32px 22px"><div style="font-size:50px">✈</div><h3 style="margin:13px 0 6px">Make time for the memorable.</h3><p class="small-note">Your first itinerary will appear here. Add your interests, duration and budget to begin.</p></div><div class="divider"></div><div class="timeline">${[['✦','Built around you','Interests, pace and budget guide recommendations.'],['◎','Real social connection','Find community-led experiences near your route.'],['▣','Useful city services','Storage and local utilities can fit into your journey.']].map(([icon,t,d])=>`<div class="timeline-item"><span class="timeline-num">${icon}</span><div class="timeline-body"><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div>`}</div></div><section class="section"><div class="story-banner"><div><div class="eyebrow">TRAVEL LIGHTER</div><h3 style="margin-top:10px">Extra hours before your flight? Make them count.</h3><p>Discover demonstration luggage storage listings, then spend your time enjoying the city instead of carrying bags.</p>${btn('Explore AUNO Stow →','data-page="stow"','secondary mt16')}</div>${img('marina')}</div></section>`}
function stowPage(){const partners=data().partners.filter(p=>S.storageArea==='All areas'||p.area===S.storageArea);const areas=['All areas',...new Set(data().partners.map(p=>p.area))];const bookings=data().storageBookings||[];
return `${header('Luggage storage','Your bags deserve a place to rest. You deserve a city to explore.',btn('Plan around your flight','data-page="journeys"','secondary'))}<div class="hero-small"><div><div class="eyebrow light">AUNO STOW / CONCEPT MARKETPLACE</div><h2>Drop your bags. Keep the memories.</h2><p>Book demonstration storage locations and see the complete booking-to-handover experience.</p></div>${img('marina')}</div><div class="notice-card mt16">All locations and rates below are fictional demonstration inventory. No real reservation, payment, insurance or luggage custody is provided.</div><section class="section">${section('Find a storage spot','Explore illustrative partner listings.')}<div class="toolbar"><div class="chipbar">${areas.map(a=>`<button class="chip ${S.storageArea===a?'active':''}" data-storage-area="${E(a)}">${E(a)}</button>`).join('')}</div>${pill('Secure partner flow · prototype','green')}</div><div class="cards-grid">${partners.map(storeCard).join('')}</div></section><section class="section">${section('Your storage reservations','Track your demo booking and handoff status.')} ${bookings.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Reservation</th><th>Storage partner</th><th>Date & times</th><th>Bags</th><th>Demo price</th><th>Status</th></tr></thead><tbody>${bookings.map(b=>`<tr><td><strong>${E(b.code)}</strong></td><td>${E(b.partner_name)}<small>${E(b.area)}</small></td><td>${E(b.date)}<small>${E(b.start_time)} – ${E(b.end_time)}</small></td><td>${b.bags}</td><td>${money(b.price)}</td><td>${pill(b.status.replace('_',' '),b.status==='collected'?'green':'orange')}</td></tr>`).join('')}</tbody></table></div>`:empty('▣','No bags booked yet','Choose a demonstration partner and explore the check-in journey.')}</section>`}
function plansPage(){return `${header('Social plans','Real adventures are better with company. Find a plan to join—or create your own.',btn('+ Create a plan','data-modal="create-plan"'))}<div class="hero-small"><div><div class="eyebrow light">SPONTANEITY MEETS COMMUNITY</div><h2>Don't do the good stuff alone.</h2><p>Turn a simple idea into a shared experience with people who want to be there.</p></div>${img('food')}</div><section class="section">${section('Open plans','Join a small, interest-led gathering.')}<div class="cards-grid">${data().plans.length?data().plans.map(planCard).join(''):empty('✣','Be the first to plan something','Create an experience and invite others.',btn('+ New plan','data-modal="create-plan"'))}</div></section>`}
function rewardsPage(){const u=me();const maxLevel=2000;const pct=Math.min(100,u.xp/maxLevel*100);const people=[...data().personas].filter(x=>x.role!=='admin'&&x.role!=='partner').sort((a,b)=>b.xp-a.xp);
return `${header('Rewards','The more you show up for life, the more you get back.')}<div class="split"><div class="panel"><div class="eyebrow">YOUR DEMO AUNO XP</div><div style="display:flex;align-items:end;gap:12px;margin:11px 0"><div class="boldnumber">${u.xp.toLocaleString()} <span style="font-size:17px;color:#7b947f">XP</span></div>${pill('Community explorer','green')}</div><p class="small-note">Earn XP when an organiser checks you into an event. Redeem your demo balance for fictional vouchers.</p><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><div class="level-track"><span>${u.xp} / ${maxLevel} XP</span><span>Next milestone</span></div></div><div class="panel"><div class="panel-head"><h3>Community leaderboard</h3>${pill('Demo XP','outline')}</div>${people.slice(0,4).map((p,i)=>`<div class="leader-row"><div class="leader-rank">${String(i+1).padStart(2,'0')}</div>${picture(p)}<div><b>${E(p.name)} ${p.id===u.id?'(you)':''}</b><small>${E(p.subtitle||'Community member')}</small></div><span class="xp">${p.xp.toLocaleString()}</span></div>`).join('')}</div></div><section class="section">${section('Your next rewards','Earn through participation. Redeem for something meaningful.')}<div class="cards-grid">${data().rewards.map(r=>`<article class="reward-card"><div class="reward-emoji">${({'coffee':'☕','trophy':'🏆','compass':'🧭'})[r.icon]||'✦'}</div><h3>${E(r.title)}</h3><p>${E(r.description)}</p><div class="meta">${E(r.partner)} · ${r.stock} demo vouchers left</div><div class="card-footer"><div class="price">${r.points} XP</div>${btn(u.xp<r.points?'Keep earning':'Redeem',u.xp<r.points?'disabled':`data-redeem="${r.id}"`,'secondary small')}</div></article>`).join('')}</div></section><section class="section">${section('Your voucher wallet','Redeemed rewards appear here.')}${data().redemptions?.length?`<div class="panel">${data().redemptions.map(r=>`<div class="member-row"><span style="font-size:21px">✧</span><div><b>${E(r.title)}</b><small>Demo voucher · Not redeemable with businesses</small></div><span class="code-pill">${E(r.code)}</span></div>`).join('')}</div>`:empty('✧','Your reward wallet is waiting','Attend events to earn XP, then choose a reward.')}</section>`}
function inboxPage(){const notices=data().notifications||[];return `${header('Inbox','The little things that keep your plans flowing.',btn('Mark all read','data-mark-read','secondary'))}<div class="panel">${notices.length?notices.map(n=>`<div class="notice-row ${n.is_read?'':'unread'}"><div class="notice-bullet">✦</div><div><b>${E(n.message)}</b><p>${E(formatDate(n.created_at))} · Demo notification</p></div>${!n.is_read?pill('New','green'):''}</div>`).join(''):empty('✉','All caught up','Booking confirmations and updates appear here.')}</div><section class="section"><div class="story-banner"><div><div class="eyebrow">AUNO + WHATSAPP</div><h3 style="margin-top:11px">Keep conversations where they're comfortable.</h3><p>Share events and plans through WhatsApp using a prefilled message. Automated delivery, group synchronisation and business APIs are not connected in this pilot.</p>${btn('Share AUNO with a friend','data-whatsapp="AUNO makes it easier to discover sports, communities and experiences together."','secondary mt16')}</div>${img('padel')}</div></section>`}
function profilePage(){const u=me();const mine=data().eventBookings||[];const communities=data().communities.filter(c=>c.membership?.status==='joined');return `${header('My profile','A little about you goes a long way toward finding the right people.',btn('Edit preferences','data-modal="preferences"','secondary'))}<div class="profile-hero">${picture(u,'lg')}<div style="flex:1"><h2>${E(u.name)}</h2><p>${E(u.subtitle||'AUNO member')}</p><div class="pill-row">${pill('● Identity sample: verified','green')}${pill(u.mode==='visitor'?'Visitor mode':'Resident mode','outline')}${pill(u.role,'outline')}</div></div><div><div class="boldnumber">${u.xp.toLocaleString()}</div><div class="small-note">Demo XP balance</div></div></div><section class="section"><div class="split"><div class="panel"><div class="panel-head"><h3>Your interests</h3>${btn('Update','data-modal="preferences"','outline small')}</div><div class="pill-row">${u.interests.length?u.interests.map(i=>pill(i,'green')).join(''):pill('Discover something new','outline')}</div><div class="divider"></div><p class="quote">The best connections start with shared curiosity. Your interests help tailor recommendations—never publish your exact location without permission.</p></div><div class="panel"><h3>Your AUNO story</h3><div class="mini-stat mt20"><span class="mini-icon">◎</span><div><strong>${communities.length} communities</strong><small>You've found your circles</small></div></div><div class="mini-stat mt20"><span class="mini-icon">✣</span><div><strong>${mine.length} active event bookings</strong><small>Experiences ahead</small></div></div><div class="mini-stat mt20"><span class="mini-icon">✧</span><div><strong>${data().redemptions.length} demo rewards</strong><small>Milestones celebrated</small></div></div></div></div></section><section class="section"><div class="panel"><div class="panel-head"><h3>Your appearance</h3>${pill('Saved on this device','outline')}</div><p class="small-note">Choose a theme or match your device settings. AUNO will remember your choice.</p><div class="mt16">${aunoThemeControls(false)}</div></div></section><section class="section"><div class="notice-card">Privacy & verification note: the pilot's verification statuses are seed data and not backed by an identity provider. Do not upload IDs or enter real sensitive information.</div></section>`}
function peoplePage(){const u=me();const peers=(data().people||[]).map(p=>({...p,shared:p.interests.filter(i=>u.interests.includes(i))})).sort((a,b)=>b.shared.length-a.shared.length);const con=data().connections||[];const incoming=con.filter(c=>c.to_id===u.id&&c.status==='pending');
return `${header('People','Meet through shared curiosity, interests and real-world experiences. Connection requests are consent-based.',btn('Find social plans','data-page="plans"','secondary'))}<div class="hero-small"><div><div class="eyebrow light">REAL PEOPLE, SHARED EXPERIENCES</div><h2>Good company changes everything.</h2><p>Discover compatible members, connect by mutual agreement and make plans through communities.</p></div>${img('food')}</div><div class="notice-card mt16">Demo people directory contains fictional profiles. In production, discovery is opt-in, location is approximate, requests are rate-limited and personal contact details remain private.</div>${incoming.length?`<section class="section">${section('Connection requests','You decide who you connect with.')}<div class="panel">${incoming.map(c=>`<div class="member-row">${picture({avatar:c.from_avatar})}<div style="flex:1"><b>${E(c.from_name)}</b><small>Wants to connect through AUNO</small></div><div class="flex gap8">${btn('Accept',`data-connection-review="${c.id}:accepted"`,'small')}${btn('Decline',`data-connection-review="${c.id}:rejected"`,'danger small')}</div></div>`).join('')}</div></section>`:''}<section class="section">${section('People you might connect with','Introductions are stronger when they start from something in common.')}<div class="cards-grid">${peers.map(p=>{const c=con.find(c=>(c.from_id===u.id&&c.to_id===p.id)||(c.from_id===p.id&&c.to_id===u.id));return `<article class="person-card"><div class="person-head">${picture(p,'lg')}<div><h3>${E(p.name)}</h3><div class="meta">${E(p.mode==='visitor'?'Visiting Dubai':'Dubai community member')}</div></div></div><div class="pill-row">${(p.shared.length?p.shared:p.interests).slice(0,3).map(i=>pill(i,p.shared.includes(i)?'green':'outline')).join('')}</div><p class="small-note">${p.shared.length?`${p.shared.length} shared interest${p.shared.length===1?'':'s'} — a great place to start.`:'Discover a new perspective together.'}</p><div class="card-footer">${pill('Sample verified profile','outline')}${c?btn(c.status==='accepted'?'Connected ✓':c.status==='pending'?(c.to_id===u.id?'Respond above':'Requested ✓'):'Not connected','disabled','secondary small'):btn('Connect',`data-connect="${p.id}"`,'secondary small')}</div></article>`}).join('')}</div></section><section class="section">${section('A better way to meet','The best connections are built through shared experiences.')}<div class="story-banner"><div><h3>Start with something you both enjoy.</h3><p>Join a circle, attend an activity or create a small-group plan. It's more natural than swiping through strangers.</p>${btn('Discover social plans →','data-page="plans"','secondary mt16')}</div>${img('padel')}</div></section>`}
function momentsPage(){const posts=data().moments||[];return `${header('Moments','A people-powered journal of places, experiences, and discoveries worth sharing.',btn('+ Share a moment','data-modal="create-moment"'))}<div class="split"><div><div class="panel"><div class="eyebrow">THE COMMUNITY JOURNAL</div><h2 style="margin-top:9px">Stories worth experiencing.</h2><p class="small-note mt10">Moments connect real places to real community experiences—not another endless social feed.</p></div>${posts.length?posts.map(m=>`<article class="moment-post"><div class="moment-author">${picture({avatar:m.author_avatar})}<div style="flex:1"><b>${E(m.author)}</b><small>${E(m.category)} · ${E(m.place)} · ${E(formatDate(m.created_at,'short'))}</small></div>${pill('Demo post','outline')}</div><p>${E(m.body)}</p><div class="moment-place">⌖ ${E(m.place)} <span>·</span> Explore together, not alone.</div><div class="moment-actions"><button data-like="${m.id}" class="${m.liked?'liked':''}">${m.liked?'♥':'♡'} &nbsp; ${m.likes} ${m.likes===1?'appreciation':'appreciations'}</button><button data-page="plans">✣ Find a plan</button><button data-report-moment="${m.id}">⚑ Report</button></div></article>`).join(''):empty('✦','No stories yet','Share something helpful you discovered.',btn('Share a moment','data-modal="create-moment"'))}</div><div><div class="panel"><div class="eyebrow">WHY WE SHARE</div><h3 style="margin:11px 0">Useful, personal, real.</h3><div class="timeline">${[['⌖','Rooted in places','Every post has a place, giving local knowledge genuine context.'],['◎','Connected to community','Join a walk, dinner or plan rather than just liking a photo.'],['♧','Safe by design','Report inappropriate content and keep member privacy in focus.']].map(([ic,t,d])=>`<div class="timeline-item"><span class="timeline-num">${ic}</span><div class="timeline-body"><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div></div><div class="panel mt20"><h3>Ready to explore?</h3><p class="small-note mt10">Go from inspiration to an actual experience.</p>${btn('Discover events →','data-page="discover"','secondary mt16')}</div></div></div>`}
function hostPage(){const h=data().host||{events:[],attendees:[]};const attendance=h.attendees||[];
return `${header('Host studio','Your community deserves an exceptional organiser experience.',btn('+ Host an event','data-modal="create-event"'))}<div class="workspace-welcome"><div><div class="eyebrow light">ORGANISER WORKSPACE</div><h2>Make every gathering count.</h2><p>Publish experiences, manage attendance and turn one-time participants into familiar faces.</p></div>${btn('Create new activity +','data-modal="create-event"','brandlime')}</div><div class="stat-grid"><div class="stat-card"><span class="glyph">▣</span><div class="label">Your events</div><div class="value">${h.events.length}</div><div class="sub">In the demo calendar</div></div><div class="stat-card"><span class="glyph">◎</span><div class="label">Reserved spots</div><div class="value">${attendance.length}</div><div class="sub">Across your activities</div></div><div class="stat-card"><span class="glyph">✓</span><div class="label">Checked in</div><div class="value">${attendance.filter(a=>a.attended).length}</div><div class="sub">Attendance records</div></div><div class="stat-card"><span class="glyph">✧</span><div class="label">XP granted</div><div class="value">${attendance.filter(a=>a.attended).length*100}</div><div class="sub">Participation recognition</div></div></div><section class="section">${section('Community membership requests','Approve applicants to your invitation-only circles.')} ${(h.membershipRequests||[]).length?`<div class="panel">${h.membershipRequests.map(r=>`<div class="member-row">${picture(r)}<div style="flex:1"><b>${E(r.name)}</b><small>Requesting to join ${E(r.community_name)}</small></div><div class="flex gap8">${btn('Approve',`data-member-review="${r.community_id}:${r.user_id}:joined"`,'small')}${btn('Decline',`data-member-review="${r.community_id}:${r.user_id}:rejected"`,'danger small')}</div></div>`).join('')}</div>`:empty('◎','All membership requests reviewed','Private circles will send membership requests here.')}</section><section class="section">${section('Your event portfolio','Everything you are hosting, in one place.')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Activity</th><th>Date & time</th><th>Where</th><th>Bookings</th><th>Capacity</th></tr></thead><tbody>${h.events.map(e=>`<tr><td><b>${E(e.title)}</b><small>${E(e.category)}</small></td><td>${E(formatDate(e.start_at))}</td><td>${E(e.area)}</td><td>${e.booked}</td><td>${e.capacity}</td></tr>`).join('')}</tbody></table></div></section><section class="section">${section('Attendance & check-in','Checking members in awards 100 demo XP once per booking.')} ${attendance.length?`<div class="panel">${attendance.map(a=>`<div class="member-row">${picture(a)}<div style="flex:1"><b>${E(a.name)}</b><small>${E(a.title)} · ${E(formatDate(a.start_at,'short'))}</small></div>${a.attended?pill('Checked in','green'):btn('Check in',`data-checkin="${a.id}"`,'secondary small')}</div>`).join('')}</div>`:empty('✓','No attendees yet','Once someone books your event, their name will appear here.')}</section><section class="section"><div class="notice-card">Pilot organiser studio. In production, hosting requires role approval, venue/event permits where applicable, event audit logs and appropriate member privacy controls.</div></section>`}
function partnerPage(){const p=data().partner||{venues:[],bookings:[]};const active=p.bookings.filter(b=>b.status!=='collected');return `${header('Partner studio','A professional operations workspace for luggage hosts and local businesses.')}<div class="workspace-welcome"><div><div class="eyebrow light">STORAGE PARTNER WORKSPACE</div><h2>Every bag. Every handoff. Accounted for.</h2><p>Review reservations, confirm bags received and record collection with a complete demonstration custody trail.</p></div>${pill('Partner account · demo','dark')}</div><div class="stat-grid"><div class="stat-card"><span class="glyph">▣</span><div class="label">Your locations</div><div class="value">${p.venues.length}</div><div class="sub">Demo storage listings</div></div><div class="stat-card"><span class="glyph">♙</span><div class="label">Total bookings</div><div class="value">${p.bookings.length}</div><div class="sub">Demonstration orders</div></div><div class="stat-card"><span class="glyph">◷</span><div class="label">Pending handoffs</div><div class="value">${active.filter(b=>b.status==='booked').length}</div><div class="sub">Awaiting drop-off</div></div><div class="stat-card"><span class="glyph">✓</span><div class="label">Bags collected</div><div class="value">${p.bookings.filter(b=>b.status==='collected').reduce((a,b)=>a+b.bags,0)}</div><div class="sub">Completed handoffs</div></div></div><section class="section">${section('Location portfolio','Locations are illustrative; no physical partner agreements exist.')}<div class="cards-grid">${p.venues.map(v=>`<div>${storeCard(v)}<button class="btn outline small mt10 full" data-edit-venue="${v.id}">Manage capacity & rates</button></div>`).join('')}</div></section><section class="section">${section('Reservation and custody queue','Use explicit state transitions; a guest must present their booking code in the real service.')} ${p.bookings.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Reference / guest</th><th>Venue</th><th>Time</th><th>Bags</th><th>Handoff</th><th>Action</th></tr></thead><tbody>${p.bookings.map(b=>`<tr><td><b>${E(b.code)}</b><small>${E(b.guest_name)}</small></td><td>${E(b.partner_name)}</td><td>${E(b.date)}<small>${E(b.start_time)} – ${E(b.end_time)}</small></td><td>${b.bags}</td><td>${pill(b.status.replace('_',' '),b.status==='collected'?'green':'orange')}</td><td>${b.status==='booked'?btn('Mark dropped off',`data-storage-status="${b.id}:dropped_off"`,'secondary small'):b.status==='dropped_off'?btn('Confirm collected',`data-storage-status="${b.id}:collected"`,'secondary small'):pill('Complete','green')}</td></tr>`).join('')}</tbody></table></div>`:empty('▣','No luggage reservations','Switch to the member persona, book storage, then return here to test the handoff flow.')}</section><section class="section"><div class="notice-card">Safety note: this prototype does not capture ID evidence, bag photos, CCTV, tamper seals, insurance coverage or signed handover records. These are launch-critical requirements, not implemented claims.</div></section>`}
function adminPage(){const a=data().admin||{overview:{},applications:[],reports:[],members:[]};const k=a.overview||{};return `${header('Operations','A clear view of the platform. Trust is a product feature, not an afterthought.')}<div class="workspace-welcome"><div><div class="eyebrow light">AUNO CONTROL CENTRE</div><h2>Great communities need great operations.</h2><p>Review new circles, resolve reports and monitor the integrity of the founding network.</p></div>${pill('Operator persona · local demo','dark')}</div><div class="stat-grid">${[['Verified demo users',k.members||0,'◎'],['Active communities',k.communities||0,'◉'],['Experience bookings',k.bookings||0,'◷'],['Storage reservations',k.storage||0,'▣']].map(([t,val,icon])=>`<div class="stat-card"><span class="glyph">${icon}</span><div class="label">${t}</div><div class="value">${val}</div><div class="sub">Prototype environment</div></div>`).join('')}</div><section class="section">${section('Community approval queue','Review every application before allowing a new community into the network.',pill(`${a.applications.length} pending`,'orange'))}${a.applications.length?`<div class="panel">${a.applications.map(ap=>`<div style="padding:15px 0;border-bottom:1px solid #edf1eb"><div class="flex justify-between align-center gap12" style="flex-wrap:wrap"><div><h3>${E(ap.name)}</h3><div class="meta" style="margin-top:5px">${E(ap.category)} · ${E(ap.area)} · Applied by ${E(ap.requester)}</div></div><div class="flex gap8">${btn('Approve ✓',`data-review="${ap.id}:approved"`,'small')}${btn('Reject',`data-review="${ap.id}:rejected"`,'danger small')}</div></div><p class="small-note mt10">${E(ap.description)}</p></div>`).join('')}</div>`:empty('✓','All proposals reviewed','There are no pending community applications.')}</section><section class="section">${section('Event publication controls','Pause or restore demonstration event listings.')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Event</th><th>Category</th><th>Visibility</th><th>Action</th></tr></thead><tbody>${(a.moderationEvents||[]).map(e=>`<tr><td><b>${E(e.title)}</b></td><td>${E(e.category)}</td><td>${pill(e.approved?'Published':'Hidden',e.approved?'green':'orange')}</td><td>${btn(e.approved?'Pause listing':'Restore',`data-event-visibility="${e.id}:${e.approved?'hide':'show'}"`,'secondary small')}</td></tr>`).join('')}</tbody></table></div></section><section class="section">${section('Social content moderation','Manage the safety of AUNO Moments.')}<div class="panel">${(a.momentsModeration||[]).map(m=>`<div class="member-row"><span class="notice-bullet">✦</span><div style="flex:1"><b>${E(m.name)}</b><small>${E(m.body.slice(0,120))}</small></div>${m.status==='visible'?btn('Hide post',`data-hide-moment="${m.id}"`,'danger small'):pill('Hidden','orange')}</div>`).join('')}</div></section><section class="section">${section('Trust & safety reports','Escalate genuine safety issues through appropriate human review.',pill(`${a.reports.length} open`,'orange'))}${a.reports.length?`<div class="panel">${a.reports.map(r=>`<div class="member-row"><span class="notice-bullet">!</span><div style="flex:1"><b>${E(r.target)} · ${E(r.reporter)}</b><small>${E(r.reason)}</small></div>${btn('Resolve demo report',`data-resolve-report="${r.id}"`,'secondary small')}</div>`).join('')}</div>`:empty('✓','No open reports','All demonstration reports have been resolved.')}</section><section class="section">${section('Member directory','Example roles and statuses; identity verification is not integrated.')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Member</th><th>Role</th><th>Mode</th><th>Demo identity</th><th>XP</th></tr></thead><tbody>${a.members.map(u=>`<tr><td><b>${E(u.name)}</b></td><td>${pill(roleName(u.role),'outline')}</td><td>${E(u.mode)}</td><td>${pill(u.verified?'Seed verified':'Not verified',u.verified?'green':'orange')}</td><td>${u.xp.toLocaleString()}</td></tr>`).join('')}</tbody></table></div></section><section class="section"><div class="notice-card">Important: the role switcher and demo header are intentionally insecure and must never be exposed in production. Production requires server-enforced login, MFA, verified organisations, fine-grained permissions and immutable audit events.</div></section>`}
function modalHtml(){if(!S.modal)return '';const {type,id}=S.modal;let body='';let cls='';if(type==='personas'){body=`<div class="form-modal"><div class="eyebrow">EXPLORE THE PLATFORM</div><h2>Choose a demo workspace</h2><p>Switch between member, community host, storage partner and AUNO operations to test connected workflows. No production login is active.</p>${data().personas.map(u=>`<button class="member-row" style="border:1px solid #e9eee8;border-radius:12px;padding:12px;margin:8px 0;width:100%;background:${u.id===S.userId?'#eaf2e9':'white'};text-align:left" data-persona="${u.id}">${picture(u)}<span style="flex:1"><b>${E(u.name)}</b><small>${E(u.subtitle||roleName(u.role))}</small></span>${u.id===S.userId?pill('Active','green'):'→'}</button>`).join('')}</div>`}
else if(type==='event'){const e=data().events.find(e=>e.id===id);if(!e)return '';body=`<div class="modal-hero">${img(e.cover,'',e.category+' illustration')}</div><div class="modal-body"><div class="flex gap8">${pill(e.category,'green')}${pill(e.level,'outline')}${pill('Demo event','orange')}</div><h2>${E(e.title)}</h2><p>${E(e.description)}</p><div class="modal-info"><div><b>◷ When</b><small>${E(formatDate(e.start_at))} · Dubai time</small></div><div><b>⌖ Where</b><small>${E(e.venue)} · ${E(e.area)}</small></div><div><b>◎ Community</b><small>${E(data().communities.find(c=>c.id===e.community_id)?.name||'AUNO event')}</small></div><div><b>◉ Availability</b><small>${e.capacity-e.booked} of ${e.capacity} spots left</small></div></div><div class="notice-card">This is a simulated event. ${money(e.price)} is an illustrative price; booking does not charge a card or secure a real-world place.</div><div class="modal-actions"><strong class="price">${money(e.price)}</strong>${btn('Share via WhatsApp',`data-whatsapp="Join me at ${E(e.title)} with AUNO"`,'outline')}${e.my_booking?btn('Cancel demo booking',`data-cancel-event="${e.id}"`,'danger'):btn(e.booked>=e.capacity?'Session full':'Reserve a spot →',e.booked>=e.capacity?'disabled':`data-book-event="${e.id}"`)}</div></div>`}
else if(type==='storage'){const p=data().partners.find(p=>p.id===id);if(!p)return '';body=`<div class="modal-hero">${img(p.cover)}</div><div class="form-modal"><div class="eyebrow">AUNO STOW / DEMO PARTNER</div><h2>${E(p.name)}</h2><p>${E(p.address)}. A demonstration booking will be saved, but no real storage is reserved.</p><div class="modal-info"><div><b>Per bag · sample</b><small>${money(p.price_per_bag)}</small></div><div><b>Example hours</b><small>${E(p.open_time)}–${E(p.close_time)}</small></div></div><form data-form="storage" data-partner="${p.id}"><div class="form-grid"><div class="field"><label>Storage date</label><input type="date" name="date" min="${today()}" value="${today()}" required></div><div class="field"><label>Number of bags</label><select name="bags">${[1,2,3,4,5,6].map(n=>`<option value="${n}">${n} ${n===1?'bag':'bags'}</option>`).join('')}</select></div><div class="field"><label>Drop-off time</label><input type="time" name="start_time" min="${p.open_time}" max="${p.close_time}" value="12:00" required></div><div class="field"><label>Collection time</label><input type="time" name="end_time" min="${p.open_time}" max="${p.close_time}" value="17:00" required></div></div><div class="notice-card mb16">Use fictional details only. No card payment, physical custody, insurance or identity check is executed.</div><button class="btn full" type="submit">Reserve demo storage →</button></form></div>`}
else if(type==='create-community'){body=`<div class="form-modal"><div class="eyebrow">COMMUNITY CREATION</div><h2>Start something meaningful.</h2><p>Propose a circle for others to join. AUNO Operations will review it before publication.</p><form data-form="create-community"><div class="form-grid"><div class="field span-all"><label>Community name</label><input name="name" placeholder="e.g. Sunrise Runners Dubai" minlength="4" maxlength="80" required></div><div class="field"><label>Category</label><select name="category"><option>Sports</option><option>Social</option><option>Adventure</option><option>Interests</option><option>Culture</option><option>Professional</option></select></div><div class="field"><label>Neighbourhood</label><input name="area" placeholder="Dubai Marina" minlength="3" required></div><div class="field span-all"><label>Your community's purpose</label><textarea name="description" placeholder="What will members do together? What makes this a welcoming place?" minlength="20" maxlength="500" required></textarea></div></div><button type="submit" class="btn full">Submit proposal for review →</button></form></div>`}
else if(type==='create-event'){body=`<div class="form-modal"><div class="eyebrow">AUNO HOST STUDIO</div><h2>Create an experience.</h2><p>Publish a demonstration event. In production, permits and operator approvals must be checked before an activity goes live.</p><form data-form="create-event"><div class="form-grid"><div class="field span-all"><label>Event name</label><input name="title" placeholder="Friday sunset padel social" minlength="4" required></div><div class="field"><label>Category</label><select name="category"><option>Padel</option><option>Badminton</option><option>Culture</option><option>Food</option><option>Adventure</option></select></div><div class="field"><label>Start · Dubai local time</label><input type="datetime-local" name="start_at" value="${future(4)}T18:00" required></div><div class="field"><label>Venue</label><input name="venue" placeholder="Partner venue name" minlength="3" required></div><div class="field"><label>Area</label><input name="area" placeholder="Dubai Marina" minlength="3" required></div><div class="field"><label>Participant capacity</label><input type="number" name="capacity" min="2" max="500" value="12" required></div><div class="field"><label>Sample price · AED</label><input type="number" name="price" min="0" max="9999" value="50" required></div><div class="field span-all"><label>Event description</label><textarea name="description" minlength="12" placeholder="What makes this gathering great?" required></textarea></div></div><button type="submit" class="btn full">Publish demo event →</button></form></div>`}
else if(type==='create-plan'){body=`<div class="form-modal"><div class="eyebrow">SOCIAL PLANS</div><h2>Good plans deserve company.</h2><p>Invite members to join an activity-led plan. For public launch, organisers and event eligibility will be checked.</p><form data-form="create-plan"><div class="form-grid"><div class="field span-all"><label>What's the plan?</label><input name="title" minlength="4" placeholder="Saturday architecture and coffee walk" required></div><div class="field"><label>Category</label><select name="category"><option>Culture</option><option>Sports</option><option>Food</option><option>Adventure</option><option>Social</option></select></div><div class="field"><label>Date and time</label><input type="datetime-local" name="start_at" value="${future(3)}T10:00" required></div><div class="field"><label>Area</label><input name="area" placeholder="Al Fahidi" minlength="3" required></div><div class="field"><label>Max participants</label><input type="number" name="seats" min="2" max="30" value="6" required></div><div class="field span-all"><label>What will you do?</label><textarea name="description" minlength="12" placeholder="A welcoming, easy-going plan to explore together." required></textarea></div></div><button type="submit" class="btn full">Create social plan →</button></form></div>`}
else if(type==='create-moment'){body=`<div class="form-modal"><div class="eyebrow">AUNO MOMENTS</div><h2>Share a useful discovery.</h2><p>Inspire people to experience the city through meaningful recommendations and community stories.</p><form data-form="create-moment"><div class="form-grid"><div class="field"><label>Place or neighbourhood</label><input name="place" minlength="3" placeholder="Al Fahidi" required></div><div class="field"><label>Category</label><select name="category"><option>Culture</option><option>Food</option><option>Sports</option><option>Adventure</option><option>Photography</option><option>Social</option></select></div><div class="field span-all"><label>Your moment</label><textarea name="body" minlength="10" maxlength="600" placeholder="What did you discover, and why would you recommend it?" required></textarea></div></div><button type="submit" class="btn full">Share moment →</button></form></div>`}
else if(type==='report'){body=`<div class="form-modal"><div class="eyebrow">TRUST & SAFETY</div><h2>Report this moment.</h2><p>Reports are routed to AUNO Operations for review. Please do not include sensitive identity information in your description.</p><form data-form="report" data-target="moment:${id}"><div class="field"><label>Tell us what needs attention</label><textarea name="reason" minlength="6" maxlength="300" placeholder="What happened?" required></textarea></div><button type="submit" class="btn full mt16">Submit report →</button></form></div>`}
else if(type==='edit-venue'){const v=data().partner?.venues?.find(x=>x.id===id);if(!v)return '';body=`<div class="form-modal"><div class="eyebrow">PARTNER INVENTORY</div><h2>Manage ${E(v.name)}</h2><p>Adjust illustrative capacity, rates and operating hours. Real partner onboarding requires verified venue and contractual checks.</p><form data-form="edit-venue" data-venue="${v.id}"><div class="form-grid"><div class="field"><label>Bag capacity</label><input name="capacity" type="number" min="1" max="500" value="${v.capacity}" required></div><div class="field"><label>Daily demo price / bag · AED</label><input name="price_per_bag" type="number" min="0" max="9999" value="${v.price_per_bag}" required></div><div class="field"><label>Opening time</label><input name="open_time" type="time" value="${E(v.open_time)}" required></div><div class="field"><label>Closing time</label><input name="close_time" type="time" value="${E(v.close_time)}" required></div></div><button type="submit" class="btn full">Save partner listing →</button></form></div>`}
else if(type==='preferences'){const u=me();body=`<div class="form-modal"><div class="eyebrow">PERSONALISE AUNO</div><h2>Make it feel like you.</h2><p>Choose your interests and switch the emphasis of recommendations between resident and visitor experiences.</p><form data-form="preferences"><div class="form-grid"><div class="field span-all"><label>How are you experiencing Dubai?</label><select name="mode"><option value="resident" ${u.mode==='resident'?'selected':''}>I'm a resident</option><option value="visitor" ${u.mode==='visitor'?'selected':''}>I'm visiting</option></select></div><div class="field span-all"><label>My interests</label><div class="chips-check">${intOptions.map(i=>`<label><input type="checkbox" value="${E(i)}" name="interests" ${u.interests.includes(i)?'checked':''}>${E(i)}</label>`).join('')}</div></div></div><button type="submit" class="btn full">Save my preferences →</button></form></div>`}
return `<div class="modal-backdrop" data-backdrop="true"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${E(type.replaceAll('-',' '))}"><button class="modal-close" aria-label="Close dialog" data-close-modal>×</button>${body}</section></div>`}
function setPage(p){S.page=p;S.filter='All';S.circleFilter='All';S.storageArea='All areas';S.modal=null;S.search='';draw();}
function openModal(type,id=null){S.modal={type,id:id===null?null:Number(id)};draw();const m=q('.modal');if(m)m.scrollTop=0;setTimeout(()=>q('.modal-close')?.focus(),10)}
function closeModal(){S.modal=null;draw()}
function whatsapp(text){const url='https://api.whatsapp.com/send?text='+encodeURIComponent(text);window.open(url,'_blank','noopener,noreferrer')}

document.addEventListener('click',async ev=>{
  const target=ev.target.closest('[data-page],[data-modal],[data-persona],[data-filter],[data-circle-filter],[data-storage-area],[data-open-event],[data-book-event],[data-cancel-event],[data-join-community],[data-open-storage],[data-join-plan],[data-redeem],[data-checkin],[data-storage-status],[data-review],[data-resolve-report],[data-mark-read],[data-mode],[data-whatsapp],[data-close-modal],[data-backdrop],[data-connect],[data-connection-review],[data-like],[data-report-moment],[data-hide-moment],[data-event-visibility],[data-member-review],[data-edit-venue],[data-theme-choice],[data-now-mood],[data-insights-days],[data-insights-category],[data-export-insights]');
  if(!target)return;
  if(target.dataset.backdrop&&ev.target===target){closeModal();return}
  if(target.hasAttribute('data-theme-choice')){window.AunoTheme?.set(target.dataset.themeChoice);draw();return}
  if(target.hasAttribute('data-now-mood')){S.nowMood=target.dataset.nowMood;draw();return}
  if(target.hasAttribute('data-insights-days')){S.insightsDays=Number(target.dataset.insightsDays);draw();return}
  if(target.hasAttribute('data-insights-category')){S.insightsCategory=target.dataset.insightsCategory;draw();return}
  if(target.hasAttribute('data-export-insights')){aunoExportInsights();toast('Demo analytics CSV downloaded.');return}
  if(target.hasAttribute('data-page')){setPage(target.dataset.page);return}
  if(target.hasAttribute('data-modal')){openModal(target.dataset.modal);return}
  if(target.hasAttribute('data-close-modal')){closeModal();return}
  if(target.hasAttribute('data-persona')){S.userId=Number(target.dataset.persona);localStorage.setItem('auno-demo-user',S.userId);S.page=null;S.modal=null;S.journey=null;await refresh();toast('Switched to '+roleName(me().role)+' demo workspace.');return}
  if(target.hasAttribute('data-filter')){S.filter=target.dataset.filter;draw();return}
  if(target.hasAttribute('data-circle-filter')){S.circleFilter=target.dataset.circleFilter;draw();return}
  if(target.hasAttribute('data-storage-area')){S.storageArea=target.dataset.storageArea;draw();return}
  if(target.hasAttribute('data-open-event')){openModal('event',target.dataset.openEvent);return}
  if(target.hasAttribute('data-open-storage')){openModal('storage',target.dataset.openStorage);return}
  if(target.hasAttribute('data-book-event')){await mutate('/events/book',{event_id:Number(target.dataset.bookEvent)},'Your demonstration activity is booked.');return}
  if(target.hasAttribute('data-cancel-event')){if(confirm('Cancel this demo booking?'))await mutate(`/events/${target.dataset.cancelEvent}/cancel`,{},'Booking cancelled.');return}
  if(target.hasAttribute('data-join-community')){const r=await mutate(`/communities/${target.dataset.joinCommunity}/join`,{},'You are connected to this community.');if(r?.status==='pending')toast('Your request is pending community approval.');return}
  if(target.hasAttribute('data-join-plan')){await mutate(`/plans/${target.dataset.joinPlan}/join`,{},'You joined the social plan.');return}
  if(target.hasAttribute('data-redeem')){if(confirm('Redeem your demo XP for this fictional voucher?')){const r=await mutate(`/rewards/${target.dataset.redeem}/redeem`,{},'Reward redeemed.');if(r)toast(`Demo voucher ${r.code} created. See your wallet below.`)}return}
  if(target.hasAttribute('data-checkin')){await mutate(`/host/bookings/${target.dataset.checkin}/checkin`,{},'Attendee checked in and XP granted.');return}
  if(target.hasAttribute('data-storage-status')){const [id,status]=target.dataset.storageStatus.split(':');if(confirm(`Confirm ${status.replace('_',' ')} in the demo custody workflow?`))await mutate(`/partner/bookings/${id}/status`,{status},'Handoff status updated.');return}
  if(target.hasAttribute('data-review')){const [id,action]=target.dataset.review.split(':');if(confirm(`${action==='approved'?'Approve':'Reject'} this community application?`))await mutate(`/admin/applications/${id}/review`,{action},'Review saved.');return}
  if(target.hasAttribute('data-resolve-report')){await mutate(`/admin/reports/${target.dataset.resolveReport}/resolve`,{},'Report resolved in demonstration queue.');return}
  if(target.hasAttribute('data-mark-read')){await mutate('/notifications/read',{},'Inbox marked as read.');return}
  if(target.hasAttribute('data-mode')){const r=await mutate('/me/preferences',{mode:target.dataset.mode,interests:me().interests},'Experience mode changed.');if(r)setPage('home');return}
  if(target.hasAttribute('data-connect')){await mutate('/connections/request',{user_id:Number(target.dataset.connect)},'Connection request sent.');return}
  if(target.hasAttribute('data-connection-review')){const [id,action]=target.dataset.connectionReview.split(':');await mutate(`/connections/${id}/review`,{action},'Connection response saved.');return}
  if(target.hasAttribute('data-like')){await mutate(`/moments/${target.dataset.like}/like`,{},'Moment updated.');return}
  if(target.hasAttribute('data-report-moment')){openModal('report',target.dataset.reportMoment);return}
  if(target.hasAttribute('data-hide-moment')){if(confirm('Hide this sample post?'))await mutate(`/admin/moments/${target.dataset.hideMoment}/hide`,{},'Post hidden.');return}
  if(target.hasAttribute('data-event-visibility')){const [id,action]=target.dataset.eventVisibility.split(':');await mutate(`/admin/events/${id}/visibility`,{action},'Event visibility updated.');return}
  if(target.hasAttribute('data-member-review')){const [cid,mid,action]=target.dataset.memberReview.split(':');await mutate(`/host/communities/${cid}/members/${mid}/review`,{action},'Membership decision saved.');return}
  if(target.hasAttribute('data-edit-venue')){openModal('edit-venue',target.dataset.editVenue);return}
  if(target.hasAttribute('data-whatsapp')){whatsapp(target.dataset.whatsapp);return}
});
document.addEventListener('change', ev=>{const t=ev.target;if(t.matches('[data-now-hours]')){S.nowTime=Number(t.value);draw()}if(t.matches('[data-now-budget]')){S.nowBudget=t.value;draw()}if(t.matches('[data-biz]')){const k=t.dataset.biz;if(k==='bookings')S.bizBookings=Number(t.value);if(k==='ticket')S.bizTicket=Number(t.value);if(k==='take')S.bizTake=Number(t.value);draw()}});
document.addEventListener('submit',async ev=>{
  const form=ev.target.closest('form[data-form]');if(!form)return;ev.preventDefault();
  const name=form.dataset.form;const fd=new FormData(form);const get=k=>String(fd.get(k)||'').trim();
  if(name==='search'){S.search=get('q');S.page='discover';S.filter='All';draw();return}
  if(name==='create-community'){await mutate('/communities/apply',{name:get('name'),category:get('category'),area:get('area'),description:get('description')},'Community proposal sent to the review queue.');return}
  if(name==='create-event'){const payload={title:get('title'),category:get('category'),venue:get('venue'),area:get('area'),start_at:get('start_at'),capacity:Number(get('capacity')),price:Number(get('price')),description:get('description')};await mutate('/host/events',payload,'Demo event published to the activity calendar.');return}
  if(name==='create-plan'){const payload={title:get('title'),category:get('category'),area:get('area'),start_at:get('start_at'),seats:Number(get('seats')),description:get('description')};await mutate('/plans',payload,'Your demo plan is published.');return}
  if(name==='storage'){const payload={partner_id:Number(form.dataset.partner),date:get('date'),start_time:get('start_time'),end_time:get('end_time'),bags:Number(get('bags'))};const r=await mutate('/storage/book',payload,'Demo luggage storage reservation created.');if(r){setPage('stow');toast(`Reservation ${r.code} created. Example charge: AED ${r.price}. No payment taken.`)}return}
  if(name==='journey'){const payload={days:Number(get('days')),area:get('area'),pace:get('pace'),budget:Number(get('budget')),interests:fd.getAll('interests').map(String),with_people:fd.has('social')};if(S.busy)return;S.busy=true;try{const r=await api('/journeys/generate','POST',payload);S.journey=r;await refresh();toast('A tailored sample itinerary was created and saved.')}catch(e){toast(e.message,true)}finally{S.busy=false}return}
  if(name==='create-moment'){await mutate('/moments',{body:get('body'),place:get('place'),category:get('category')},'Your moment is visible to the demo community.');return}
  if(name==='report'){await mutate('/reports',{target:form.dataset.target,reason:get('reason')},'Report submitted to demo operations queue.');return}
  if(name==='edit-venue'){await mutate(`/partner/venues/${form.dataset.venue}`,{capacity:Number(get('capacity')),price_per_bag:Number(get('price_per_bag')),open_time:get('open_time'),close_time:get('close_time')},'Partner location updated.');return}
  if(name==='preferences'){const payload={mode:get('mode'),interests:fd.getAll('interests').map(String)};const r=await mutate('/me/preferences',payload,'Preferences saved.');if(r)setPage('profile');return}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&S.modal)closeModal()});
refresh().catch(err=>{q('#app').innerHTML=`<div class="boot-screen"><div class="boot-mark">a</div><h2>Unable to connect to AUNO</h2><p>${E(err.message)}. Please refresh or clear this site's demo storage.</p></div>`});
